let created = SecurityIncident | where TimeGenerated {TimeRange} | summarize Created = dcount(IncidentNumber);
let open = SecurityIncident | where TimeGenerated {TimeRange} | summarize arg_max(TimeGenerated, *) by IncidentNumber | where Status =~ "New" or Status =~ "Active" | count | project Open = Count;
let closed = SecurityIncident | where TimeGenerated {TimeRange} | summarize arg_max(TimeGenerated, *) by IncidentNumber | where Status =~ "Closed" | count | project Closed = Count;
created | extend dummy = 1 | join kind=inner (open | extend dummy = 1) on dummy | join kind=inner (closed | extend dummy = 1) on dummy | project Created, Open, Closed
